dir$tlhccong.prototype = new DirEvent();
dir$tlhccong.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
  document._dir = this._dir;
}
function getSystemTime(format) {
    return new Promise(function(resolve, reject) {
        $.ajax({
            type: "POST",
            url: "/Main/Defaults.aspx/GetSystemTime",
            contentType: "application/json; charset=utf-8",
            dataType: "json",
            data: JSON.stringify({ format: format }),
            success: function(response) {
                var systemTime = response.d;
                resolve(systemTime);
            },
            error: function(error) {
                reject(error);
            }
        });
    });
}
function getTime(p, className) {
	const inputEl = document.querySelector(`input.${className}`);
	console.log(inputEl);
    if (!inputEl) return;

    let isValid = false;

    inputEl.addEventListener("input", function (e) {
        let raw = e.target.value.replace(/\D/g, "").slice(0, 4); // Giữ lại 4 chữ số đầu
        let formatted = raw;

        if (raw.length >= 3) {
            formatted = `${raw.slice(0, 2)}:${raw.slice(2, 4)}`;
        }

        e.target.value = formatted;

		const [h, m] = formatted.split(":").map(Number);
        isValid = Number.isInteger(h) && Number.isInteger(m) && h >= 0 && h <= 23 && m >= 0 && m <= 59;

    });

    inputEl.addEventListener("blur", async (e) => {
        if (!isValid && e.target.value.trim() !== "") {
            try {
                const [hh, mm] = await Promise.all([
                    getSystemTime("HH"),
                    getSystemTime("mm")
                ]);
                e.target.value = `${hh}:${mm}`;
            } catch (err) {
                console.error("Lỗi lấy giờ hệ thống:", err);
            }
        } else {
            console.log("✅ Giờ hợp lệ:", e.target.value);
        }
    });
}
dir$tlhccong.prototype.afterInit = function(renderType){
  var p = this._dir;
  getTime(p,'tg_lamviec');
  dir$tlhccongDisabledMasterField(p);
  dir$tlhccongDisabledStatusByAction(p);

}

dir$tlhccong.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'ok':
		var sttBd = p.valForm('stt_bd'), sttTd = p.valForm('stt_td'), tgDukien = p.valForm('tg_dukien'), tgTrihoan = p.valForm('tg_trihoan');

		if (isNaN(sttBd) || sttBd <= 0) {
			$.showToast(p.msg('RequireLonHonKhong'));
			p.jObject('stt_bd').focus(); 
			return false;
		}
		if (isNaN(sttTd) || sttTd <= 0) {
			$.showToast(p.msg('RequireLonHonKhong'));
			p.jObject('stt_td').focus(); 
			return false;
		}
		if (isNaN(tgDukien) || tgDukien <= 0) {
			$.showToast(p.msg('RequireLonHonKhong'));
			p.jObject('tg_dukien').focus(); 
			return false;
		}
		if (isNaN(tgTrihoan) || tgTrihoan <= 0) {
			$.showToast(p.msg('RequireLonHonKhong'));
			p.jObject('tg_trihoan').focus(); 
			return false;
		}
    default:
      break;
  }
  return true;
}
dir$tlhccong.prototype.beforeButtonGridClick = function (id, gindex) {

  var p = this._dir;
  switch (id) {
    case '20':
		break;
    default:
