dir$tlhccong.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$tlhccongDisabledMasterField(p);
  return true;
}

function dir$tlhccongDisabledMasterField(p){
	if (p.options.action !== "NEW")
	{
		p.setDisabled(['unit_id', 'ngay_ct', 'so_ct'], true);
	}

}


function dir$tlhccongDisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=4],[value=6],[value=7],[value=9],[value=5],[value=0]").remove();
}







